#include <variant>
#include <type_traits>
using M = std::monostate;
using V = std::variant<M, int>;
int main() {
  return !std::is_same_v<M, std::variant_alternative_t<0, V>> ||
         !std::is_same_v<const M, std::variant_alternative_t<0, const V>> ||
         std::variant_size_v<V> != 2;
}

