}

#include <variant>
int main() {
  std::variant<int, int> value(std::in_place_index<1>, 31);
  auto* selected = std::get_if<1>(&value);
  return value.index() != 1 || !selected || *selected != 31 || std::get_if<0>(&value);
}

#include <variant>
int main() {
  std::variant<int, long> value(std::in_place_index<1>);
